diff --git a/src/factura.mjs b/src/factura.mjs
index 5d01137..d405bba 100644
--- a/src/factura.mjs
+++ b/src/factura.mjs
@@ -15,7 +15,12 @@ export function calcularFactura(items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    const bruto = item.cantidad * item.precioUnitarioCentavos;
+    // RF-004: descuento en porcentaje (0 a 100) por línea, antes del total, redondeado al centavo.
+    const descuento = item.descuentoPorcentaje ?? 0;
+    if (typeof descuento !== "number" || !Number.isFinite(descuento) || descuento < 0 || descuento > 100)
+      throw new RangeError("Descuento inválido: debe estar entre 0 y 100");
+    totalCentavos += Math.round((bruto * (100 - descuento)) / 100);
   }
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
   return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..bdb7247 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,17 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+test("RF-004: descuento por línea en porcentaje", () => {
+  const f = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 }]);
+  assert.equal(f.totalCentavos, 1800);
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: 100 }]).totalCentavos, 0);
+  // redondeo al centavo: 333 * 33 % de descuento = 223,11 -> 223
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 333, descuentoPorcentaje: 33 }]).totalCentavos, 223);
+  assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: 101 }]), RangeError);
+  assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: -1 }]), RangeError);
+  assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: NaN }]), RangeError);
+});
